      LessonBlock.paragraph("Ab board par misaalein hal karte hain. Har misaal ke sath wajah bhi samjho, sirf jawab mat dekho."),
      LessonBlock.example("Aik square ki side 5 metre hai. Us ke gird baarh lagani hai aur andar tiles bhi lagani hain. Dono ka hisaab nikalo.", note: "Baarh perimeter hai, 4 × 5 = 20 metre. Tiles area hai, 5 × 5 = 25 square metre. Dekho, aik hi shakal, do sawal, aur dono ke jawab aur ikaiyan alag hain."),
      LessonBlock.example("Aik bagh 8 metre lamba aur 5 metre chora hai. Us ka area aur perimeter nikalo.", note: "Area barabar 8 × 5 = 40 square metre. Perimeter barabar 2 × (8 + 5) = 2 × 13 = 26 metre."),
      LessonBlock.example("Aik khet 40 metre lamba aur 25 metre chora hai. Us ke chaaron taraf baarh lagani hai. Baarh kitni lambi hogi?", note: "Baarh sirf kinara hai, yani perimeter. 2 × (40 + 25) = 2 × 65 = 130 metre. Area wala 1000 yahan lagana hi ghalti hai jo paper azmata hai."),
      LessonBlock.example("Aik kamra 6 metre lamba aur 4 metre chora hai. Farsh par aik square metre wali tiles lagani hain. Kitni tiles lagengi?", note: "Tiles jagah gherengi, yani area. 6 × 4 = 24 square metre, to 24 tiles lagengi."),
      LessonBlock.example("Aik triangle ka base 10 centimetre aur height 6 centimetre hai. Us ka area nikalo.", note: "Pehle poora rectangle socho, 10 × 6 = 60. Triangle us ka aadha hai, to area barabar 30 square centimetre. Formula se bhi yahi hai, 1/2 × 10 × 6 = 30."),
      LessonBlock.example("Aik triangle ki teen sides 3, 4 aur 5 centimetre hain. Us ka perimeter nikalo.", note: "Teeno ka jama, 3 + 4 + 5 = 12 centimetre. Perimeter me koi guna taqseem nahi, sirf chaaron, yani teeno taraf ki lambaiyon ka jama hai."),
      LessonBlock.example("Aik gol thaali ka radius 7 centimetre hai. Us ke kinare ki lambai, yani circumference, nikalo.", note: "Circumference barabar 2πr, yani 2 × 22/7 × 7. Neeche wala 7 upar wale 7 se kat gaya, jawab 44 centimetre."),
      LessonBlock.example("Wohi gol shakal, radius 7 centimetre, us ka area nikalo.", note: "Area barabar πr², yani 22/7 × 7 × 7. Aik 7 kat gaya, reh gaya 22 × 7 = 154 square centimetre. Gaur karo, circumference 44 centimetre thi aur area 154 square centimetre hai. Numbers bhi alag, ikaiyan bhi alag."),
      LessonBlock.example("Aik pahiye ka diameter 70 centimetre hai. Wo aik chakar me kitna faasla tay karta hai?", note: "Pehla qadam, radius nikalo. Diameter ka aadha, 70 / 2 = 35 centimetre. Aik chakar ka faasla circumference ke barabar hai, 2 × 22/7 × 35 = 220 centimetre."),
      LessonBlock.example("Aik triangle ke do konay 50 degree aur 60 degree hain. Teesra kona kitna hoga?", note: "Teeno ka jama 180 hota hai. Pehle do ka jama 110 hai. 180 − 110 = 70 degree. Teesra kona 70 degree ka hai."),
      LessonBlock.heading("Ye kahan kaam aata hai"),
